import{_ as n,l as s,o as e,c as i,v as t,p as l,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"值范围分析","description":"","frontmatter":{"title":"值范围分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/value-range-analysis.md","filePath":"cs/value-range-analysis.md","lastUpdated":1789023840000}'),h={name:"cs/value-range-analysis.md"};function u(_,a,m,f,A,E){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="值范围分析" tabindex="-1">值范围分析 <a class="header-anchor" href="#值范围分析" aria-label="Permalink to &quot;值范围分析&quot;">​</a></h1><div class="epigraph"><p>在格上跟踪整数可能取值的区间或位掩码：比较可折成常量，无符号越界检查可删，switch 可变紧凑。</p><footer>—— 据 Cousot 区间域；Harrison 的范围分析实践；龙书与 LLVM ValueTracking 整理</footer></div><p>上一课<a href="/cs/partial-redundancy-elim">PRE</a>移动表达式。缺口是<strong>值的约束</strong>：<code>if (x&gt;=0 &amp;&amp; x&lt;n)</code> 之后 <code>x</code> 的范围。值范围分析（VRA）是<a href="/cs/abstract-interpretation">抽象解释</a>的区间/位域在 SSA 上的应用。本课钉用途，不写完整八边形域。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常量传播只认单点。范围：<code>[0,255]</code> 使 <code>x&amp;255</code> 变恒等，<code>x&lt;256</code> 变真。缺口是<strong>分支后的收紧</strong>（与 SCCP 的控制流敏感同类），服务消除检查与选择指令。</p><p>位域：已知低位为零则对齐。与<a href="/cs/strength-reduction-iv">归纳变量</a>：IV 的闭式给出精确范围。</p><h3 id="范围不是类型" tabindex="-1">范围不是类型 <a class="header-anchor" href="#范围不是类型" aria-label="Permalink to &quot;范围不是类型&quot;">​</a></h3><p><code>uint8</code> 的类型范围是 <code>[0,255]</code>；分析可更窄。类型系统的 Option 与范围分析互补：一个是语言，一个是 IR 事实。</p><p><span class="marginnote">Cousot 区间。GCC VRP。LLVM 的 ConstantRange / LazyValueInfo。本课可靠 over-approx：真实值 ⊆ 区间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>格：区间，交为收紧，并为合并（φ、未知枝）。加宽防循环升链。分支：真枝交上谓词。</p>',11)),(e(),l(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SSA%5B%22SSA%20%E5%90%8D%22%5D%20--%3E%20RNG%5B%22%E5%8C%BA%E9%97%B4%20%2F%20%E4%BD%8D%22%5D%0A%20%20BR%5B%22%E5%88%86%E6%94%AF%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20RNG%0A%20%20RNG%20--%3E%20FOLD%5B%22%E6%8A%98%E6%AF%94%E8%BE%83%20%2F%20%E5%88%A0%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 UB：有符号溢出若 UB，分析可假设不溢出以收紧——危险与后课 UB 优化同一刀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指针范围（对象内偏移）服务越界消除，须 provenance。不要把分析当沙箱。浮点范围更少用，NaN 破坏全序。</p><p>PGO 可提供热范围，但是动态的，须与静态可靠分开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写关系域（<code>x&lt;y</code>）全文。后课默认：整数范围可消比较。下一课 SSA 构造：许多分析假设 SSA，该把 φ 插对。</p><p>也不把范围当依赖类型 <code>Fin n</code> 的替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>值范围：区间/位格，分支收紧。</li><li>用于折比较、删冗余检查、助向量化。</li><li>可靠近似；循环要加宽。</li><li>出处：Cousot；GCC VRP / LLVM ConstantRange；对照 Wegman SCCP。</li></ul>',9))])}const C=n(h,[["render",u]]);export{x as __pageData,C as default};
